bool dfs(int curr, vector<int> adj[], vector<int> &rec, vector<int> &vis)
{
    if (rec[curr])
        return true;

    struct Frame {
        int node;
        size_t idx;
    };

    std::stack<Frame> st;
    st.push({curr, 0});
    rec[curr] = 1;

    while (!st.empty()) {
        Frame &fr = st.top();
        int u = fr.node;

        if (fr.idx < adj[u].size()) {
            int v = adj[u][fr.idx++];
            if (rec[v])
                return true;
            if (!vis[v]) {
                rec[v] = 1;
                st.push({v, 0});
            }
        } else {
            vis[u] = 1;
            rec[u] = 0;
            st.pop();
        }
    }
    return false;
}

