void permute(string str, string out, set<string> &ans)
{
  struct Frame {
    string str;
    string out;
    size_t idx;
  };

  std::vector<Frame> st;
  st.push_back({str, out, 0});

  while (!st.empty()) {
    Frame &fr = st.back();

    if (fr.str.empty()) {
      ans.insert(fr.out);
      st.pop_back();
      continue;
    }
    if (fr.idx >= fr.str.size()) {
      st.pop_back();
      continue;
    }

    string child_str = fr.str.substr(1);
    string child_out = fr.out + fr.str[0];

    fr.idx++;
    rotate(fr.str.begin(), fr.str.begin() + 1, fr.str.end());

    st.push_back({child_str, child_out, 0});
  }
}

