    while (!st.empty()) {
        int cur = st.top();
        st.pop();
        if (cur == 1) continue;

        std::string say = current;
        std::string next;
        next.reserve(say.size() * 2);
        for (size_t i = 0; i < say.size(); ) {
            size_t j = i + 1;
            while (j < say.size() && say[j] == say[i]) ++j;
            next += std::to_string(j - i);
            next.push_back(say[i]);
            i = j;
        }
        current = std::move(next);
    }
    return current;
}

