char kthCharacter(long long k, vector<int>& operations) {
    // Explicit stack replaces the recursive call stack
    std::stack<long long> st;
    st.push(k);

    int totalIncrements = 0;

    while (!st.empty()) {
        long long curK = st.top();
        st.pop();

        if (curK == 1) {
            continue; // base case reached
        }

        long long len = 1;
        int opType = 0;
        long long newK = curK;
        int n = operations.size();

        for (int i = 0; i < n; ++i) {
            len <<= 1; // len *= 2
            if (len >= curK) {
                opType = operations[i];
                newK = curK - len / 2; // k > len/2 is guaranteed here
                break;
            }
        }

        if (opType == 1) {
            ++totalIncrements;
        }

        st.push(newK); // push the item the recursive call would have been made on
    }

    char res = 'a';
    for (int i = 0; i < totalIncrements; ++i) {
        res = (res == 'z') ? 'a' : res + 1;
    }
    return res;
}

