int find(vector<int>& parent, int i) {
    std::stack<int> st;
    st.push(i);

    int root = i;
    while (!st.empty()) {
        int cur = st.top();
        if (parent[cur] == cur) {
            root = cur;
            break;
        }
        st.push(parent[cur]);
    }

    // Path compression: set all nodes on the stack to point directly to root
    while (!st.empty()) {
        int node = st.top();
        st.pop();
        parent[node] = root;
    }
    return root;
}

