int find(int A[], int x)
{
    std::stack<int> path;
    int cur = x;
    while (cur != A[cur]) {
        path.push(cur);
        cur = A[cur];
    }
    int root = cur;
    while (!path.empty()) {
        A[path.top()] = root;
        path.pop();
    }
    return root;
}

