void insert(stack<int> &s, int t)
{
    // explicit work list that replaces the recursive call stack
    struct Frame {
        int t;
        int temp;
        bool afterRecursion;
    };
    std::stack<Frame> st;
    st.push({t, 0, false});

    while (!st.empty()) {
        Frame f = st.top();
        st.pop();

        if (!f.afterRecursion) {
            if (s.empty() || s.top() < f.t) {
                s.push(f.t);
            } else {
                f.temp = s.top();
                s.pop();
                // schedule the push-back that happens after the recursive call
                st.push({f.t, f.temp, true});
                // schedule the recursive call with the same t
                st.push({f.t, 0, false});
            }
        } else {
            s.push(f.temp);
        }
    }
}

