#include <stack>
using namespace std;

int minimumSteps(int a, int b, int c) {
    struct State { int a; int b; int c; };
    std::stack<State> st;
    st.push({a, b, c});

    while (!st.empty()) {
        State cur = st.top();
        st.pop();
        int aa = cur.a;
        int bb = cur.b;
        int cc = cur.c;

        if (aa < 1 || bb < 1) return -1;
        if (aa == 1 && bb == 1) return cc;

        if (aa < bb) {
            // explicit swap, equivalent to original a=a+b; b=a-b; a=a-b;
            int tmp = aa;
            aa = bb;
            bb = tmp;
        }
        // push the state that the recursive call would have processed
        st.push({aa - bb, bb, cc + 1});
    }
    return -1;
}

