int minPalPartion(string String,int i,int j) {
    if(i>j) return 0;
    struct Item{int i;int j;};
    stack<Item> st;
    vector<Item> order;
    unordered_map<long long,int> memo;
    auto key = [](int a,int b)->long long{ return ((long long)a<<32) | (unsigned int)b; };
    st.push({i,j});
    while(!st.empty()){
        Item cur = st.top(); st.pop();
        long long k = key(cur.i,cur.j);
        if(memo.find(k)!=memo.end()) continue;
        if(cur.i>=cur.j || isPalindrome(String,cur.i,cur.j)){
            memo[k]=0;
            continue;
        }
        order.push_back(cur);
        for(int kIdx=cur.i;kIdx<cur.j;kIdx++){
            st.push({cur.i,kIdx});
            st.push({kIdx+1,cur.j});
        }
    }
    for(int idx=(int)order.size()-1; idx>=0; --idx){
        Item cur = order[idx];
        int best = INT_MAX;
        for(int kIdx=cur.i;kIdx<cur.j;kIdx++){
            int left = memo[key(cur.i,kIdx)];
            int right = memo[key(kIdx+1,cur.j)];
            best = min(best, left + right + 1);
        }
        memo[key(cur.i,cur.j)] = best;
    }
    return memo[key(i,j)];
}

