void accumulate_arr(int arr[], int len) {
  if (len <= 1) return;
  std::stack<std::pair<int,bool>> st;
  st.push({len, false});
  while (!st.empty()) {
    auto [cur, done] = st.top();
    st.pop();
    if (cur <= 1) continue;
    if (!done) {
      st.push({cur, true});
      st.push({cur - 1, false});
    } else {
      arr[cur - 1] += arr[cur - 2];
    }
  }
}

