#include <vector>
using namespace std;

int dfs(int n, int index, vector<int>& row,
            vector<bool>& col, vector<bool>& dia1, vector<bool>& dia2){
    int res = 0;

    struct State {
        int idx;
        vector<int> row;
        vector<char> col;
        vector<char> d1;
        vector<char> d2;
    };

    auto toChar = [](const vector<bool>& v){
        vector<char> c(v.size());
        for (size_t i = 0; i < v.size(); ++i) c[i] = v[i];
        return c;
    };

    std::stack<State> st;
    State start;
    start.idx = index;
    start.row = row;
    start.col = toChar(col);
    start.d1   = toChar(dia1);
    start.d2   = toChar(dia2);
    st.push(std::move(start));

    while (!st.empty()) {
        State cur = std::move(st.top());
        st.pop();

        if (cur.idx == n) {
            ++res;
            continue;
        }

        for (int i = 0; i < n; ++i) {
            if (!cur.col[i] && !cur.d1[cur.idx + i] && !cur.d2[cur.idx - i + n - 1]) {
                State nxt;
                nxt.idx = cur.idx + 1;
                nxt.row = cur.row;
                nxt.row.push_back(i);
                nxt.col = cur.col;
                nxt.col[i] = 1;
                nxt.d1 = cur.d1;
                nxt.d1[cur.idx + i] = 1;
                nxt.d2 = cur.d2;
                nxt.d2[cur.idx - i + n - 1] = 1;
                st.push(std::move(nxt));
            }
        }
    }
    return res;
}

