    struct State {
        int idx;
        int A;
        int B;
        int taken;
    };
    std::stack<State> st;
    st.push({idx, A, B, 0});
    int best = 0;
    while(!st.empty()) {
        State cur = st.top();
        st.pop();
        if(cur.idx == (int)vec.size()) {
            if(cur.taken > best) best = cur.taken;
            continue;
        }
        // exclude current string -> corresponds to recursive exc call
        st.push({cur.idx + 1, cur.A, cur.B, cur.taken});
        // include current string -> corresponds to recursive inc call
        int zero = count0(vec[cur.idx]);
        int one = (int)vec[cur.idx].size() - zero;
        if(zero <= cur.A && one <= cur.B) {
            st.push({cur.idx + 1, cur.A - zero, cur.B - one, cur.taken + 1});
        }
    }
    return best;
}
