bool isWinning(int pos) {
  if (pos < 0) return false;
  const int moves[3] = {1, 3, 4};
  std::vector<char> memo(pos + 1, -1);
  memo[0] = 0;

  struct Frame { int pos; int idx; };
  std::stack<Frame> st;
  st.push({pos, 0});

  while (!st.empty()) {
    Frame &fr = st.top();
    int p = fr.pos;

    if (memo[p] != -1) { st.pop(); continue; }
    if (p == 0) { memo[p] = 0; st.pop(); continue; }

    if (fr.idx < 3) {
      int m = moves[fr.idx++];
      if (p >= m) {
        int child = p - m;
        if (memo[child] == -1) {
          st.push({child, 0});
          continue;
        } else if (memo[child] == 0) {
          memo[p] = 1;
          st.pop();
          continue;
        }
      }
      continue;
    } else {
      memo[p] = 0;
      st.pop();
    }
  }
  return memo[pos] == 1;
}

