int getR(int index, const vector<int>& height, vector<int>& rdp){
    if(index < 0 || index >= (int)height.size()) return -1;
    std::stack<int> st;
    st.push(index);
    std::vector<int> order;
    order.reserve(height.size() - index);
    while(!st.empty()){
        int i = st.top(); st.pop();
        order.push_back(i);
        if(i + 1 < (int)height.size()){
            st.push(i + 1);
        }
    }
    int suffix_max = 0;
    for(int k = (int)order.size() - 1; k >= 0; --k){
        int i = order[k];
        if(i == (int)height.size() - 1){
            rdp[i] = height[i];
            suffix_max = height[i];
        }else{
            suffix_max = std::max(height[i], suffix_max);
            rdp[i] = suffix_max;
        }
    }
    return rdp[index];
}

