void array_increment(int arr[], int len) {
    if (len <= 0) return;

    struct Frame {
        int len;
        bool visited;
    };

    std::stack<Frame> st;
    st.push({len, false});

    while (!st.empty()) {
        Frame f = st.top();
        st.pop();
        if (f.len == 0) continue;

        if (!f.visited) {
            // push current frame for post-processing, then its child
            st.push({f.len, true});
            st.push({f.len - 1, false});
        } else {
            // post-order work that was done after the recursive call
            arr[f.len - 1] += f.len - 1;
