#include <stack>

int arr_sum(int arr[], int len) {
    if (len <= 0) return 0;
    // explicit call stack replacing the implicit recursion
    std::stack<int> st;
    st.push(len);
    int sum = 0;
    while (!st.empty()) {
        int curLen = st.top();
        st.pop();
        if (curLen <= 0) continue;
        // the recursive call would be arr_sum(arr, curLen-1)
        // we push the child frame first, then account for the current frame's addition
        if (curLen > 1) {
            st.push(curLen - 1);
        }
        sum += arr[curLen - 1];
    }
    return sum;
}

