#include <stack>

int solve(int y, int x, int s) {
    struct Frame {
        int y;
        int x;
        int s;
        long long acc;
    };
    std::stack<Frame> st;
    st.push({y, x, s, 0});
    long long result = 0;
    while (!st.empty()) {
        Frame cur = st.top();
        st.pop();
        if (cur.s == 2) {
            result = cur.acc + 2LL * cur.y + cur.x;
            break;
        }
        int ns = cur.s >> 1;
        int ny = cur.y / ns;
        int nx = cur.x / ns;
        int nxt = ny * 2 + nx;
        long long newAcc = cur.acc + 1LL * ns * ns * nxt;
        int ry = cur.y - ny * ns;
        int rx = cur.x - nx * ns;
        st.push({ry, rx, ns, newAcc});
    }
    return static_cast<int>(result);
}

