using std::vector;
using std::stack;

int ComputeNumberOfWaysToH(int h, int maximum_step,
                           vector<int>* number_of_ways_to_h_ptr) {
  if (h <= 1) {
    return 1;
  }

  vector<int>& number_of_ways_to_h = *number_of_ways_to_h_ptr;
  if (number_of_ways_to_h[h] != 0) {
    return number_of_ways_to_h[h];
  }

  struct Frame {
    int h;
    int next_i;
  };

  stack<Frame> st;
  st.push({h, 1});

  while (!st.empty()) {
    Frame &fr = st.top();
    int cur = fr.h;

    if (cur <= 1) {
      number_of_ways_to_h[cur] = 1;
      st.pop();
      continue;
    }

    if (number_of_ways_to_h[cur] != 0) {
      st.pop();
      continue;
    }

    if (fr.next_i > maximum_step || cur - fr.next_i < 0) {
      long long sum = 0;
      for (int i = 1; i <= maximum_step && cur - i >= 0; ++i) {
        sum += number_of_ways_to_h[cur - i];
      }
      number_of_ways_to_h[cur] = static_cast<int>(sum);
      st.pop();
      continue;
    }

    int child = cur - fr.next_i;
    ++fr.next_i;

    if (child < 0) {
      continue;
    }
    if (child <= 1) {
      number_of_ways_to_h[child] = 1;
      continue;
    }
    if (number_of_ways_to_h[child] == 0) {
      st.push({child, 1});
    }
  }

  return number_of_ways_to_h[h];
}

