            }
            f.stage = 1;
            st.push({f.b, f.p / 2, 0, 0});
        } else {
            int sq = f.childRes;
            sq = sq * sq;
            if (f.p % 2 == 1) sq = sq * f.b;
            f.childRes = sq;
            if (st.size() == 1) {
