#include <unordered_map>

int min_int(int x, int y) {
    return (x < y) ? x : y;
}

int utility_fun_for_del(std::string str, int i, int j) {
    if (i >= j) return 0;

    struct Frame {
        int i;
        int j;
        bool processed;
    };

    std::stack<Frame> st;
    st.push({i, j, false});

    auto key = [](int a, int b) -> long long {
        return ( (static_cast<long long>(a) << 32) | static_cast<unsigned int>(b) );
    };

    std::unordered_map<long long, int> memo;

    while (!st.empty()) {
        Frame cur = st.top();
        st.pop();
        long long k = key(cur.i, cur.j);
        if (memo.find(k) != memo.end()) continue;

        if (cur.i >= cur.j) {
            memo[k] = 0;
            continue;
        }

        if (!cur.processed) {
            if (str[cur.i] == str[cur.j]) {
                st.push({cur.i, cur.j, true});
                st.push({cur.i + 1, cur.j - 1, false});
            } else {
                st.push({cur.i, cur.j, true});
                st.push({cur.i + 1, cur.j, false});
                st.push({cur.i, cur.j - 1, false});
            }
        } else {
            if (str[cur.i] == str[cur.j]) {
                long long childKey = key(cur.i + 1, cur.j - 1);
                int childRes = memo.count(childKey) ? memo[childKey] : 0;
                memo[k] = childRes;
            } else {
                long long k1 = key(cur.i + 1, cur.j);
                long long k2 = key(cur.i, cur.j - 1);
                int r1 = memo.count(k1) ? memo[k1] : 0;
                int r2 = memo.count(k2) ? memo[k2] : 0;
                memo[k] = 1 + min_int(r1, r2);
            }
        }
    }
    return memo[key(i, j)];
}

int min_ele_del(std::string str) {
    if (str.empty()) return 0;
    return utility_fun_for_del(str, 0, static_cast<int>(str.length()) - 1);
}

