void pairStar(string& input, string& output, int i = 0) {
    if (input.empty()) {
        return;
    }
    if (i < 0 || i >= (int)input.size()) {
        return;
    }

    std::stack<int> st;
    st.push(i);

    while (!st.empty()) {
        int idx = st.top();
        st.pop();

        output += input[idx];

        if (idx == (int)input.size() - 1) {
            continue;
        }

        if (input[idx] == input[idx + 1]) {
            output += '*';
        }

        st.push(idx + 1);
    }
}

