int reduceToOne(int N) {
    if (N == 1) {
        return 0;
    }
    std::stack<int> st;
    st.push(N);
    int steps = 0;
    while (!st.empty()) {
        int cur = st.top();
        st.pop();
        if (cur == 1) {
            continue;
        }
        ++steps;
        if (isPowerOfTwo(cur)) {
            st.push(cur / 2);
        } else {
            st.push(cur - highestPowerof2(cur));
        }
    }
    return steps;
}

