using namespace std;

int eggDrop(int n, int k) {
    if (k <= 1) return k;
    if (n == 1) return k;

    vector<vector<int>> dp(n + 1, vector<int>(k + 1, 0));
    for (int i = 1; i <= n; ++i) dp[i][1] = 1;
    for (int j = 1; j <= k; ++j) dp[1][j] = j;

    struct Item { int n; int k; };
    stack<Item> st;
    for (int i = 2; i <= n; ++i) {
        for (int j = 2; j <= k; ++j) {
            st.push({i, j});
        }
    }

    while (!st.empty()) {
        Item cur = st.top(); st.pop();
        int best = INT_MAX;
        for (int x = 1; x <= cur.k; ++x) {
            int res = max(dp[cur.n - 1][x - 1], dp[cur.n][cur.k - x]);
            if (res < best) best = res;
        }
        dp[cur.n][cur.k] = best + 1;
    }
    return dp[n][k];
}

