string ConstructFromBase(int num_as_int, int base) {
  if (num_as_int == 0) return "";
  std::stack<int> numStack;
  std::stack<char> digitStack;
  numStack.push(num_as_int);
  while (!numStack.empty()) {
    int cur = numStack.top();
    numStack.pop();
    int rem = cur % base;
    char digit = static_cast<char>(rem >= 10 ? 'A' + rem - 10 : '0' + rem);
    digitStack.push(digit);
    int next = cur / base;
    if (next != 0) {
      numStack.push(next);
