#include <iostream>
#include <stack>
#include <vector>
using namespace std;

int oneDigit(int num) {
    return num >= 0 && num < 10;
}

bool isPalUtil(int num, int* dupNum) {
    struct Frame { int num; int stage; };
    std::stack<Frame> st;
    st.push({num, 0});
    bool result = true;
    while (!st.empty()) {
        Frame &f = st.top();
        if (f.stage == 0) {
            if (oneDigit(f.num)) {
                result = (f.num == (*dupNum) % 10);
                st.pop();
                if (st.empty()) return result;
            } else {
                f.stage = 1;
                st.push({f.num / 10, 0});
            }
        } else {
            *dupNum /= 10;
            if (f.num % 10 != (*dupNum) % 10) {
                return false;
            }
            st.pop();
        }
    }
    return result;
}

int isPal(int num) {
    if (num < 0) num = -num;
    int dupNum = num;
    return isPalUtil(num, &dupNum);
}

void printPalPrimesLessThanN(int n) {
    vector<char> prime(n + 1, true);
    if (n >= 0) prime[0] = false;
    if (n >= 1) prime[1] = false;
    for (int p = 2; p * p <= n; ++p) {
        if (prime[p]) {
            for (int i = p * p; i <= n; i += p) prime[i] = false;
        }
    }
    for (int p = 2; p <= n; ++p) {
        if (prime[p] && isPal(p)) cout << p << " ? ";
    }
}

