#include <stack>
#include <algorithm>

int getL(int index, const vector<int>& height, vector<int>& ldp){
    if (index < 0) return 0;
    std::stack<int> callStack;
    std::stack<int> pending;
    callStack.push(index);

    while (!callStack.empty()) {
        int i = callStack.top();
        callStack.pop();

        if (i == 0) {
            ldp[i] = height[i];
            // unwind the pending frames in LIFO order, exactly as the recursive returns would
            while (!pending.empty()) {
                int j = pending.top();
                pending.pop();
                ldp[j] = std::max(height[j], ldp[j - 1]);
            }
            break;
        } else {
            // simulate the recursive call getL(i-1)
            pending.push(i);
            callStack.push(i - 1);
        }
    }
    return ldp[index];
}

