NestedInteger deserializeHelper(const string& s, int *i) {
    int idx = *i;
    if (idx >= (int)s.size()) return NestedInteger();
    if (s[idx] != '[') {
        int j = idx;
        while (j < (int)s.size() && (s[j] == '-' || isdigit(s[j]))) ++j;
        NestedInteger res;
        res.setInteger(stoi(s.substr(idx, j - idx)));
        *i = j;
        return res;
    }

    std::stack<NestedInteger> st;
    NestedInteger root;
    st.push(root);
    idx++; // skip '['

    while (idx < (int)s.size()) {
        char c = s[idx];
        if (c == '[') {
            NestedInteger child;
            st.push(child);
            ++idx;
        } else if (c == ']') {
            NestedInteger finished = st.top();
            st.pop();
            if (st.empty()) {
                *i = idx + 1;
                return finished;
            }
            st.top().add(finished);
            ++idx;
        } else if (c == ',') {
            ++idx;
        } else if (c == '-' || isdigit(c)) {
            int start = idx;
            while (idx < (int)s.size() && (s[idx] == '-' || isdigit(s[idx]))) ++idx;
            int val = stoi(s.substr(start, idx - start));
            NestedInteger num;
            num.setInteger(val);
            st.top().add(num);
        } else {
            ++idx;
        }
    }
    *i = idx;
    return st.top();
}

