    std::stack<node*> st;
    std::stack<node*> order;
    st.push(root);
    while(!st.empty()){
        node* cur = st.top(); st.pop();
        order.push(cur);
        if(cur->left)  st.push(cur->left);
        if(cur->right) st.push(cur->right);
    }
    unordered_map<node*,int> best;
    while(!order.empty()){
        node* cur = order.top(); order.pop();
        int size_excl = 0;
        int size_incl = 1;
        if(cur->left){
