using namespace std;

int getMinSquares(unsigned int n) {
    if (n == 0) return 0;
    unsigned int r = static_cast<unsigned int>(std::sqrt(static_cast<double>(n)));
    if (r * r == n) return 1;
    if (n <= 3) return static_cast<int>(n);

    // BFS from n down to 0 replaces the recursive call stack.
    // The shortest path length in the graph n -> n - k*k is the minimal number of squares.
    vector<int> dist(n + 1, -1);
    queue<unsigned int> q;
    q.push(n);
    dist[n] = 0;

    while (!q.empty()) {
        unsigned int cur = q.front(); q.pop();
        for (unsigned int x = 1; x * x <= cur; ++x) {
            unsigned int nxt = cur - x * x;
            if (dist[nxt] == -1) {
                dist[nxt] = dist[cur] + 1;
                if (nxt == 0) return dist[nxt];
                q.push(nxt);
            }
        }
    }
    return dist[0];
}

